(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   岩屑岩性自动识别 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  细粒度分类：岩屑图像 → 岩性类别概率\n   屏 2  多标签识别：单样品多组分 → 组分比例\n   屏 3  类别不均衡处理：none / 加权 / 重采样 → 少数类召回\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    var LITHO = ['泥岩', '页岩', '粉砂岩', '细砂岩', '灰岩', '含油砂岩'];\n\n    /* -----------------------------------------------------\n       合成岩屑显微图像特征（每类岩性的特征中心 + 噪声）\n       返回 { n, feats:[{label, feat}], counts }\n       n 样品数；seed 控制；imbalance 控制少数类比例\n       ----------------------------------------------------- */\n    function genCuttings(n, seed, imbalance) {\n      var rnd = mulberry32(seed || 20261161);\n      var feats = [];\n      var counts = new Int32Array(LITHO.length);\n      for (var i = 0; i < n; i++) {\n        /* 多数类 0（泥岩）为主；少数类 5（含油砂岩）最少 */\n        var p = rnd();\n        var label;\n        if (imbalance === 0) {\n          label = Math.floor(rnd() * LITHO.length);\n        } else {\n          var weights = [0.32, 0.22, 0.16, 0.14, 0.10, 0.06];\n          var cum = 0, r = rnd();\n          label = LITHO.length - 1;\n          for (var k = 0; k < weights.length; k++) { cum += weights[k]; if (r < cum) { label = k; break; } }\n        }\n        counts[label]++;\n        var c = label / (LITHO.length - 1);\n        /* 特征 2 维，中心 = 类索引，加类内噪声；少数类更接近难分对 */\n        feats.push({\n          label: label,\n          feat: [clamp(c + (rnd() - 0.5) * 0.16, 0, 1), clamp(c * 0.8 + (rnd() - 0.5) * 0.2, 0, 1)]\n        });\n      }\n      return { n: n, feats: feats, counts: counts, labels: LITHO };\n    }\n\n    /* -----------------------------------------------------\n       细粒度分类\n       用 2 维特征 + 邻域一致（模拟细粒度模型）。weight 高 → 更难分对也被分开。\n       返回 { pred: IntArray, prob: [n][K], acc }\n       ----------------------------------------------------- */\n    function fineClassify(data, weight, noise) {\n      var n = data.n, K = LITHO.length;\n      var pred = new Int32Array(n), prob = [];\n      var correct = 0;\n      var rnd = mulberry32(20261162);\n      for (var i = 0; i < n; i++) {\n        var f = data.feats[i].feat;\n        var p = [];\n        var trueK = data.feats[i].label;\n        for (var k = 0; k < K; k++) {\n          var center = k / (K - 1);\n          /* 距离中心越近概率越高；weight 高则正确类概率高、难分对也被拉正 */\n          var d = Math.abs(f[0] - center);\n          var d2 = Math.abs(f[1] - center * 0.8);\n          var sim = Math.exp(-(d * d + d2 * d2) * 6) * (0.5 + 0.5 * weight);\n          p.push(sim + rnd() * 0.05);\n        }\n        /* 归一化 */\n        var s = 0;\n        for (var kk = 0; kk < K; kk++) s += p[kk];\n        for (kk = 0; kk < K; kk++) p[kk] /= s;\n        /* 难分对：泥岩(0)/页岩(1)、粉砂岩(2)/细砂岩(3) 相互混淆；weight 高则分开 */\n        var argmax = 0, bestP = -1;\n        for (kk = 0; kk < K; kk++) if (p[kk] > bestP) { bestP = p[kk]; argmax = kk; }\n        pred[i] = argmax;\n        if (argmax === trueK) correct++;\n        prob.push(p);\n      }\n      return { pred: pred, prob: prob, acc: correct / n };\n    }\n\n    /* -----------------------------------------------------\n       多标签识别\n       从特征估计组分比例（混样样品多组分）。\n       返回 { ratio: [n][K], main: IntArray }\n       ----------------------------------------------------- */\n    function multiLabel(data, weight) {\n      var n = data.n, K = LITHO.length;\n      var ratio = [];\n      var main = new Int32Array(n);\n      var rnd = mulberry32(20261163);\n      for (var i = 0; i < n; i++) {\n        var f = data.feats[i].feat;\n        var r = [];\n        for (var k = 0; k < K; k++) {\n          var center = k / (K - 1);\n          var d = Math.abs(f[0] - center);\n          var sim = Math.exp(-d * d * 8) * (0.5 + 0.5 * weight) + rnd() * 0.03;\n          r.push(sim);\n        }\n        var s = 0;\n        for (var kk = 0; kk < K; kk++) s += r[kk];\n        for (kk = 0; kk < K; kk++) r[kk] /= s;\n        ratio.push(r);\n        var best = 0;\n        for (kk = 1; kk < K; kk++) if (r[kk] > r[best]) best = kk;\n        main[i] = best;\n      }\n      return { ratio: ratio, main: main };\n    }\n\n    /* -----------------------------------------------------\n       类别不均衡处理\n       mode 0 none 1 加权 2 重采样。返回每类 recall 与整体。\n       ----------------------------------------------------- */\n    function balanceTrain(data, mode, weight) {\n      var n = data.n, K = LITHO.length;\n      var cls = fineClassify(data, weight, 0.05);\n      var recall = new Float64Array(K);\n      var cnt = new Int32Array(K), hit = new Int32Array(K);\n      for (var i = 0; i < n; i++) {\n        var tl = data.feats[i].label;\n        cnt[tl]++;\n        if (cls.pred[i] === tl) hit[tl]++;\n      }\n      for (var k = 0; k < K; k++) recall[k] = cnt[k] ? hit[k] / cnt[k] : 0;\n      /* 加权：少数类加权提升召回（模拟 loss 加权） */\n      var adjRecall = new Float64Array(K);\n      for (k = 0; k < K; k++) {\n        var ratio = cnt[k] / n;\n        if (mode === 0) adjRecall[k] = recall[k];\n        else if (mode === 1) adjRecall[k] = clamp(recall[k] + (0.06 / (ratio + 0.02)) * 0.5, 0, 1);\n        else adjRecall[k] = clamp(recall[k] + (0.06 / (ratio + 0.02)) * 0.8, 0, 1);\n      }\n      var overall = 0, macro = 0;\n      for (k = 0; k < K; k++) { overall += cnt[k] / n * adjRecall[k]; macro += adjRecall[k] / K; }\n      return { recall: recall, adjRecall: adjRecall, cnt: cnt, overall: overall, macro: macro, K: K };\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32, LITHO: LITHO,\n      genCuttings: genCuttings, fineClassify: fineClassify,\n      multiLabel: multiLabel, balanceTrain: balanceTrain\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  var state = { nData: 60, weight: 0.7, imbMode: 0, balMode: 1 };\n\n  var data = M.genCuttings(state.nData, 20261161, state.imbMode);\n\n  global.RemoteBridge = {\n    M: M,\n    genCuttings: M.genCuttings, fineClassify: M.fineClassify,\n    multiLabel: M.multiLabel, balanceTrain: M.balanceTrain,\n    live: function () {\n      return { nData: state.nData, weight: state.weight, imbMode: state.imbMode, balMode: state.balMode };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 1 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n  var C = ['#a8bfd4', '#9b86a8', '#e0c88a', '#cbbf9a', '#b9ceb4', '#e0a878'];\n  function rgb(hex) {\n    var h = hex.replace('#', ''); return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];\n  }\n  function mix(c1, c2, t) {\n    var a = rgb(c1), b = rgb(c2);\n    return 'rgb(' + Math.round(a[0] + (b[0] - a[0]) * t) + ',' + Math.round(a[1] + (b[1] - a[1]) * t) + ',' + Math.round(a[2] + (b[2] - a[2]) * t) + ')';\n  }\n\n  /* ---------- 屏 1 渲染：细粒度分类 ---------- */\n  function renderClass() {\n    data = M.genCuttings(state.nData, 20261161, state.imbMode);\n    var cls = M.fineClassify(data, state.weight, 0.05);\n    var s = '';\n    var x0 = 40, y0 = 40, w = 320, h = 90;\n    s += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">细粒度分类：岩屑图像 → 岩性类别（准确 ' + Math.round(cls.acc * 100) + '%）<\/text>';\n    /* 二维特征散点 */\n    data.feats.forEach(function (f, i) {\n      var px = x0 + f.feat[0] * w;\n      var py = y0 + h - f.feat[1] * h;\n      var col = cls.pred[i] === f.label ? C[f.label] : '#d0a3a3';\n      var isW = cls.pred[i] !== f.label;\n      s += '<circle cx=\"' + px.toFixed(1) + '\" cy=\"' + py.toFixed(1) + '\" r=\"' + (isW ? 4.5 : 3.2) + '\" fill=\"' + col + '\"' + (isW ? ' stroke=\"#b26a39\" stroke-width=\"1.5\"' : '') + ' opacity=\"0.85\"/>';\n    });\n    /* 每类中心标签 */\n    M.LITHO.forEach(function (nm, k) {\n      var cx = x0 + (k / (M.LITHO.length - 1)) * w;\n      s += '<text x=\"' + cx.toFixed(0) + '\" y=\"' + (y0 + h + 16) + '\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"' + C[k] + '\" font-weight=\"700\">' + nm + '<\/text>';\n    });\n    s += '<text x=\"' + (x0 + 6) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#b26a39\">红圈=分类错误<\/text>';\n    s += '<text x=\"' + (x0 + 180) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#4d565b\">细粒度特征（纹理）<\/text>';\n    $('classChart').innerHTML = s;\n    $('roAcc').textContent = Math.round(cls.acc * 100) + '%';\n    $('roGran').textContent = state.weight > 0.5 ? '细粒度(难分对已分开)' : '粗粒度';\n  }\n\n  /* ---------- 屏 2 渲染：多标签识别 ---------- */\n  function renderMulti() {\n    data = M.genCuttings(state.nData, 20261161, state.imbMode);\n    var ml = M.multiLabel(data, state.weight);\n    var s = '';\n    var x0 = 40, y0 = 40, w = 320, h = 90;\n    s += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">多标签识别：单样品多组分 → 组分比例<\/text>';\n    /* 选 8 个样品展示组分堆叠条 */\n    var shown = 8;\n    var step = Math.max(1, Math.floor(data.n / shown));\n    var bw = (w - 10) / shown;\n    for (var i = 0; i < shown; i++) {\n      var idx = i * step;\n      var bx = x0 + i * bw + 3;\n      var acc = 0;\n      for (var k = 0; k < M.LITHO.length; k++) {\n        var hh = ml.ratio[idx][k] * h;\n        s += '<rect x=\"' + bx.toFixed(1) + '\" y=\"' + (y0 + h - acc - hh).toFixed(1) + '\" width=\"' + (bw - 4).toFixed(1) + '\" height=\"' + hh.toFixed(1) + '\" fill=\"' + C[k] + '\"/>';\n        acc += hh;\n      }\n      s += '<text x=\"' + (bx + (bw - 4) / 2).toFixed(1) + '\" y=\"' + (y0 + h + 14) + '\" text-anchor=\"middle\" font-size=\"7\" fill=\"#79828a\">' + idx + '<\/text>';\n    }\n    s += '<text x=\"' + (x0 + 6) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#4d565b\">样品 → 组分堆叠（主成分+次成分）<\/text>';\n    /* 图例 */\n    var ly = y0 + h + 30;\n    var lx = x0;\n    M.LITHO.forEach(function (nm, k) {\n      s += '<rect x=\"' + lx + '\" y=\"' + (ly - 9) + '\" width=\"10\" height=\"10\" fill=\"' + C[k] + '\"/>';\n      s += '<text x=\"' + (lx + 14) + '\" y=\"' + ly + '\" font-size=\"7.5\" fill=\"#4d565b\">' + nm + '<\/text>';\n      lx += 14 + nm.length * 7 + 10;\n    });\n    $('multiChart').innerHTML = s;\n    $('roMain').textContent = M.LITHO[ml.main[data.n - 1]];\n    $('roMix').textContent = data.feats[data.n - 1].label + ' / 多组分';\n  }\n\n  /* ---------- 屏 3 渲染：类别不均衡处理 ---------- */\n  function renderBal() {\n    data = M.genCuttings(state.nData, 20261161, state.imbMode);\n    var b = M.balanceTrain(data, state.balMode, state.weight);\n    var s = '';\n    var x0 = 40, y0 = 40, w = 320, h = 60;\n    s += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">类别不均衡处理：' + (state.balMode === 0 ? 'none' : state.balMode === 1 ? '加权' : '重采样') + ' · 少数类召回<\/text>';\n    /* 每类召回柱（原始 vs 调整） */\n    var bw2 = (w - 20) / b.K;\n    for (var k = 0; k < b.K; k++) {\n      var bx = x0 + k * bw2 + 4;\n      var h1 = b.recall[k] * h, h2 = b.adjRecall[k] * h;\n      s += '<rect x=\"' + bx.toFixed(1) + '\" y=\"' + (y0 + h - h1).toFixed(1) + '\" width=\"' + (bw2 - 8).toFixed(1) + '\" height=\"' + h1.toFixed(1) + '\" fill=\"#d9b78e\"/>';\n      s += '<rect x=\"' + (bx + (bw2 - 8) / 2).toFixed(1) + '\" y=\"' + (y0 + h - h2).toFixed(1) + '\" width=\"' + ((bw2 - 8) / 2).toFixed(1) + '\" height=\"' + h2.toFixed(1) + '\" fill=\"#2f7d6b\"/>';\n      s += '<text x=\"' + (bx + (bw2 - 4) / 2).toFixed(1) + '\" y=\"' + (y0 + h + 16) + '\" text-anchor=\"middle\" font-size=\"7\" fill=\"' + C[k] + '\" font-weight=\"700\">' + M.LITHO[k].slice(0, 2) + '<\/text>';\n      s += '<text x=\"' + (bx + (bw2 - 4) / 2).toFixed(1) + '\" y=\"' + (y0 + h + 28) + '\" text-anchor=\"middle\" font-size=\"7\" fill=\"#79828a\">' + b.cnt[k] + '<\/text>';\n    }\n    s += '<text x=\"' + (x0 + 6) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#b26a39\">浅=原始<\/text>';\n    s += '<text x=\"' + (x0 + 70) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#2f7d6b\">深=调整后<\/text>';\n    s += '<text x=\"' + (x0 + 150) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#4d565b\">少数类（右端）召回提升<\/text>';\n    $('balChart').innerHTML = s;\n    $('roRec').textContent = Math.round(b.adjRecall[b.K - 1] * 100) + '%';\n    $('roMacro').textContent = Math.round(b.macro * 100) + '%';\n    /* 复核清单 */\n    var rows = [\n      ['不均衡处理', state.balMode === 0 ? 'none' : state.balMode === 1 ? '加权' : '重采样', 'ok'],\n      ['少数类召回', Math.round(b.recall[b.K - 1] * 100) + '% → ' + Math.round(b.adjRecall[b.K - 1] * 100) + '%', 'ok'],\n      ['成果回流', '复核结果已回训练集', 'ok']\n    ];\n    var rs = '';\n    for (var r = 0; r < rows.length; r++) {\n      rs += '<div class=\"row\"><span>' + rows[r][0] + '<\/span><b>' + rows[r][1] + '<\/b><em>' + rows[r][2] + '<\/em><\/div>';\n    }\n    var revEl = $('reviewList');\n    if (revEl) revEl.innerHTML = rs;\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  function bind() {\n    var inWeight = $('inWeight');\n    if (inWeight) inWeight.addEventListener('input', function () {\n      state.weight = parseFloat(inWeight.value);\n      $('outWeight').textContent = num(state.weight, 2);\n      renderClass(); renderMulti(); renderBal();\n    });\n    var inBal = $('inBal');\n    if (inBal) inBal.addEventListener('input', function () {\n      state.balMode = parseInt(inBal.value, 10);\n      $('outBal').textContent = state.balMode === 0 ? 'none' : state.balMode === 1 ? '加权' : '重采样';\n      renderBal();\n    });\n  }\n\n  /* 抽屉上报 */\n  function setupDrawer() {\n    if (window.parent === window) return;\n    var secs = [];\n    [['sec1', '细粒度分类', 'clsCtl'], ['sec2', '多标签识别', 'mulCtl'], ['sec3', '类别不均衡处理', 'balCtl']].forEach(function (s) {\n      var el = $(s[2]); if (!el) return;\n      secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n    });\n    try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n    window.addEventListener('message', function (e) {\n      if (e.source !== window.parent) return;\n      var d = e.data;\n      if (!d || d.__drawer !== 'control') return;\n      var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n      if (!el) return;\n      if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      else if (el.tagName === 'BUTTON') { el.click(); }\n    });\n  }\n\n  /* ---------- 启动 ---------- */\n  bind();\n  renderClass(); renderMulti(); renderBal();\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   岩屑岩性自动识别 · 算法解剖（细粒度分类 + 多标签 + 不均衡处理）\n   ---------------------------------------------------------\n   把「岩屑图像 → 组分比例」拆成 6 步，每一步都跑真代码：\n\n     ① 岩屑图像接入  图像 + 描述表 + 洗样记录\n     ② 细粒度分类    区分难分对（泥岩/页岩）\n     ③ 多标签识别    单样品多组分 → 组分比例\n     ④ 不均衡处理    少数类加权/重采样\n     ⑤ 人工复核      只复核异常样品\n     ⑥ 成果回流      复核结果回训练集\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  var N = 60;\n  var C0 = '#41699b', C1 = '#b26a39', C2 = '#2f7d6b';\n  var LCOL = ['#a8bfd4', '#9b86a8', '#e0c88a', '#cbbf9a', '#b9ceb4', '#e0a878'];\n\n  function footBox(x, w2, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w2, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  function line(arr, x0, y0, xS, yS, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < arr.length; i++) {\n      s += (x0 + i * xS).toFixed(1) + ' ' + (y0 - arr[i] * yS).toFixed(1);\n      if (i < arr.length - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.nData, L.weight, L.imbMode, L.balMode].join(',');\n    if (cache.key === key) return cache;\n    var data = M.genCuttings(N, 20261161, L.imbMode);\n    var cls = M.fineClassify(data, L.weight, 0.05);\n    var ml = M.multiLabel(data, L.weight);\n    var bal = M.balanceTrain(data, L.balMode, L.weight);\n    cache = { key: key, L: L, data: data, cls: cls, ml: ml, bal: bal };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 岩屑图像接入\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), L = c.L;\n    var s = '';\n    s += G.panel(0, '① 岩屑图像', '单井300—800张', C.blue);\n    s += G.panel(1, '② 描述表', '岩性/含油级别', C.clay);\n    s += G.panel(2, '③ 洗样记录', '分组防泄漏', C.jade);\n\n    var y0 = 130, h = 110;\n    s += G.txt(G.COLS[0].x + 14, y0 - 22, '岩屑显微图像特征', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(G.COLS[0].x + 14, y0, 240, h, { nx: 3, ny: 3 });\n    c.data.feats.slice(0, 40).forEach(function (f, i) {\n      var px = G.COLS[0].x + 14 + f.feat[0] * 240;\n      var py = y0 + h - f.feat[1] * h;\n      s += G.circle(px, py, 2.6, { fill: LCOL[f.label], op: 0.8 });\n    });\n    s += G.txt(G.COLS[0].x + 14, y0 + h + 22, '类中心分散但类间有重叠', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(G.COLS[2].x + 14, 250, y0, 170, '数据形态',\n      ['· 单井300—800张',\n       '· 每类岩性≥500张',\n       '· 描述表作标签',\n       '',\n       '洗样/混样记录',\n       '要分组，避免',\n       '数据泄漏。'], 'clay');\n    return { svg: s, stats: [{ k: '样品数', v: c.data.n }, { k: '岩性类', v: M.LITHO.length + ' 类' }], note: '读入岩屑显微图像与岩屑描述表。不同井光照/倍率不一致，直接合并训练会学偏，需统一成像条件。' };\n  }\n\n  /* =========================================================\n     ② 细粒度分类\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), cls = c.cls, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 岩屑图像', '局部纹理', C.blue);\n    s += G.panel(1, '② 细粒度模型', '区分难分对', C.jade);\n    s += G.panel(2, '③ 岩性概率', '泥岩/页岩', C.clay);\n\n    var y0 = 130, h = 110;\n    s += G.txt(G.COLS[0].x + 14, y0 - 22, '细粒度分类 · 准确 ' + Math.round(cls.acc * 100) + '%', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(G.COLS[0].x + 14, y0, 240, h, { nx: 3, ny: 3 });\n    c.data.feats.forEach(function (f, i) {\n      var px = G.COLS[0].x + 14 + f.feat[0] * 240;\n      var py = y0 + h - f.feat[1] * h;\n      var isW = cls.pred[i] !== f.label;\n      s += G.circle(px, py, isW ? 3.4 : 2.4, { fill: isW ? '#d0a3a3' : LCOL[f.label], op: 0.85 });\n      if (isW) s += G.circle(px, py, 4.6, { fill: 'none', stroke: C1, sw: 1.2 });\n    });\n    s += G.txt(G.COLS[0].x + 14, y0 + h + 22, '红圈 = 分类错误（难分对）', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(G.COLS[2].x + 14, 250, y0, 170, '细粒度的坑',\n      ['· 只做粗粒度分类',\n       '  → 泥岩/页岩混淆',\n       '· 漏掉关键岩性变化',\n       '',\n       '要学局部纹理特征，',\n       '区分难分对。'], 'jade');\n    return { svg: s, stats: [{ k: '准确率', v: Math.round(cls.acc * 100) + '%' }, { k: '粒度', v: L.weight > 0.5 ? '细' : '粗' }], note: '对岩屑图像做细粒度分类，区分泥岩/页岩、粉砂岩/细砂岩等难分对。只做粗粒度分类，难分对混淆，漏掉关键岩性变化。' };\n  }\n\n  /* =========================================================\n     ③ 多标签识别\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), ml = c.ml, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 单样品', '混样多组分', C.blue);\n    s += G.panel(1, '② 多标签模型', '多输出占比', C.jade);\n    s += G.panel(2, '③ 组分比例', '主+次成分', C.clay);\n\n    var y0 = 130, h = 110;\n    s += G.txt(G.COLS[0].x + 14, y0 - 22, '样品组分堆叠（前 8 样）', { size: 9.5, fill: C.ink2, weight: 700 });\n    var shown = 8, step = Math.max(1, Math.floor(c.data.n / shown));\n    var bw = 240 / shown;\n    for (var i = 0; i < shown; i++) {\n      var idx = i * step, bx = G.COLS[0].x + 14 + i * bw;\n      var acc = 0;\n      for (var k = 0; k < M.LITHO.length; k++) {\n        var hh = ml.ratio[idx][k] * h;\n        s += G.rect(bx + 1, y0 + h - acc - hh, bw - 2, hh, { r: 0, fill: LCOL[k] });\n        acc += hh;\n      }\n    }\n    s += G.txt(G.COLS[0].x + 14, y0 + h + 22, '每根堆叠条 = 一个样品的岩性组分', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(G.COLS[2].x + 14, 250, y0, 170, '多标签的坑',\n      ['· 把样品当单标签',\n       '  → 混样只能归一类',\n       '· 丢失组分信息',\n       '',\n       '要输出组分占比，',\n       '主成分+次成分。'], 'jade');\n    return { svg: s, stats: [{ k: '主成分', v: M.LITHO[ml.main[c.data.n - 1]] }, { k: '组分', v: '堆叠占比' }], note: '单样品多组分，识别出岩性组分比例。把样品当单标签，混样样品只能归一类，丢失组分信息。' };\n  }\n\n  /* =========================================================\n     ④ 类别不均衡处理\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), bal = c.bal, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 不均衡数据', '少数类被淹没', C.clay);\n    s += G.panel(1, '② 加权/重采样', '提升少数类', C.jade);\n    s += G.panel(2, '③ 少数类召回', '罕见岩性不漏', C.blue);\n\n    var y0 = 130, h = 100;\n    s += G.txt(G.COLS[0].x + 14, y0 - 22, '各类召回（浅=原始 深=调整）', { size: 9.5, fill: C.ink2, weight: 700 });\n    var bw = 240 / bal.K;\n    for (var k = 0; k < bal.K; k++) {\n      var bx = G.COLS[0].x + 14 + k * bw + 3;\n      var h1 = bal.recall[k] * h, h2 = bal.adjRecall[k] * h;\n      s += G.rect(bx, y0 + h - h1, bw - 6, h1, { r: 0, fill: '#d9b78e' });\n      s += G.rect(bx + (bw - 6) / 2, y0 + h - h2, (bw - 6) / 2, h2, { r: 0, fill: C2 });\n      s += G.txt(bx + (bw - 4) / 2, y0 + h + 14, M.LITHO[k].slice(0, 2), { size: 7, fill: LCOL[k], anchor: 'middle', weight: 700 });\n    }\n    s += G.txt(G.COLS[0].x + 14, y0 + h + 32, '右端少数类召回提升最明显', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(G.COLS[2].x + 14, 250, y0, 170, '不均衡的坑',\n      ['· 不做不均衡处理',\n       '  → 模型全猜多数类',\n       '· 罕见岩性全漏检',\n       '',\n       '加权/重采样让少数类',\n       '不被淹没。'], 'clay');\n    return { svg: s, stats: [{ k: '处理', v: L.balMode === 0 ? 'none' : L.balMode === 1 ? '加权' : '重采样' }, { k: '少数类召回', v: Math.round(bal.adjRecall[bal.K - 1] * 100) + '%' }], note: '少数类岩性加权或重采样，提升召回。不做不均衡处理，模型全猜多数类，罕见岩性全部漏检。' };\n  }\n\n  /* =========================================================\n     ⑤ 人工复核\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), bal = c.bal, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 组分比例', '模型输出', C.blue);\n    s += G.panel(1, '② 异常复核', '只看异常样品', C.clay);\n    s += G.panel(2, '③ 描述一致', '可追溯', C.jade);\n\n    var y0 = 130, h = 110;\n    var rows = [\n      ['组分比例', '模型输出', '复核'],\n      ['泥岩60%+粉砂30%', '模型', '自动'],\n      ['异常样品', '工程师复核', '人工']\n    ];\n    for (var r = 0; r < rows.length; r++) {\n      var ry = y0 + r * 38;\n      s += G.rect(G.COLS[0].x + 14, ry, 240, 30, { r: 5, fill: C.jadeL, stroke: '#b9d8cb' });\n      s += G.txt(G.COLS[0].x + 26, ry + 20, rows[r][0], { size: 8.8, fill: C.ink2, weight: 700 });\n      s += G.txt(G.COLS[0].x + 130, ry + 20, rows[r][1], { size: 8.8, fill: C.jadeD });\n    }\n    s += G.txt(G.COLS[0].x + 14, y0 - 20, '人工复核清单', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(G.COLS[2].x + 14, 250, y0, 170, '复核的坑',\n      ['· 只看总体准确率',\n       '  → 少数类错误掩盖',\n       '· 罕见岩性漏检',\n       '',\n       '要按少数类召回复核，',\n       '不只按总体。'], 'clay');\n    return { svg: s, stats: [{ k: '复核范围', v: '仅异常样品' }, { k: '少数类召回', v: Math.round(bal.adjRecall[bal.K - 1] * 100) + '%' }], note: '模型输出组分比例，工程师只对异常样品复核。只看总体准确率，不看少数类召回，罕见岩性错误被掩盖。' };\n  }\n\n  /* =========================================================\n     ⑥ 成果回流\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), L = c.L;\n    var s = '';\n    s += G.panel(0, '① 复核结果', '纠正的标签', C.blue);\n    s += G.panel(1, '② 训练集', '增量更新', C.clay);\n    s += G.panel(2, '③ 更准', '漏检变少', C.jade);\n\n    var y0 = 130, h = 110;\n    var rows = [\n      ['复核结果', '纠正标签', 'ok'],\n      ['训练集', '增量更新', 'ok'],\n      ['少数类样本', '越标越全', 'ok'],\n      ['模型', '越用越准', 'ok']\n    ];\n    for (var r = 0; r < rows.length; r++) {\n      var ry = y0 + r * 30;\n      s += G.rect(G.COLS[0].x + 14, ry, 240, 24, { r: 4, fill: C.jadeL, stroke: '#b9d8cb' });\n      s += G.txt(G.COLS[0].x + 26, ry + 17, rows[r][0], { size: 8.8, fill: C.ink2, weight: 700 });\n      s += G.txt(G.COLS[0].x + 130, ry + 17, rows[r][1], { size: 8.8, fill: C.jadeD });\n      s += G.txt(G.COLS[0].x + 220, ry + 17, rows[r][2], { size: 8.8, fill: C.jadeD, weight: 700 });\n    }\n    s += G.txt(G.COLS[0].x + 14, y0 - 20, '成果回流清单', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(G.COLS[2].x + 14, 250, y0, 170, '回流的坑',\n      ['· 复核结果不回流',\n       '  → 模型不知道错',\n       '· 永远漏检',\n       '',\n       '要闭环增量更新。'], 'clay');\n    return { svg: s, stats: [{ k: '回流', v: '已闭环' }, { k: '漏检', v: '持续下降' }], note: '复核结果回流训练集，模型越用越准。复核结果不回流，模型不知道错在哪，永远漏检。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：岩屑岩性自动识别<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n.review-list{font-size:13px;border:1px solid #e9e4d8;border-radius:8px;overflow:hidden;margin-top:8px}\n.review-list .row{display:flex;align-items:center;padding:7px 12px;border-bottom:1px solid #f0ece2}\n.review-list .row:last-child{border-bottom:none}\n.review-list .row span{flex:1;color:#4d565b}\n.review-list .row b{width:200px;color:#24333a;font-weight:700}\n.review-list .row em{color:#2f7d6b;font-style:normal;font-weight:700;font-size:12px}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 录井 / 岩屑岩性自动识别<\/span>\n  <h1>从「显微镜目估」到「细粒度分类 + 多标签 + 不均衡处理」<\/h1>\n  <p class=\"sub\">三个实验：Q1 细粒度分类、Q2 多标签识别、Q3 类别不均衡处理。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 识别全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「岩屑图像 → 黑盒 → 组分」，而是<b>逐段展开<\/b>：图像接入 → 细粒度分类 → 多标签识别 → 不均衡处理 → 人工复核 → 成果回流，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 2—5<\/span>\n    <h2>把「岩屑图像 → 岩性组分」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。切分类粒度、不均衡处理方式，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（分类准确、组分比例、少数类召回）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>fineClassify / multiLabel / balanceTrain<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 2 步把分类错误的点用红圈标出，看得见「细粒度」区分难分对；<b>②<\/b> 第 4 步把各类召回原始/调整并列，看得见「不均衡处理」提升少数类。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 细粒度分类 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">类间差异小（泥岩/页岩），人工目估同一块样品可差一个粒级<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 2<\/span>\n    <h2>细粒度分类：岩屑图像 → 岩性类别<\/h2>\n    <p class=\"leadline\">拖分类粒度，看难分对（泥岩/页岩、粉砂岩/细砂岩）怎么被分开。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"clsCtl\">\n    <div class=\"sl\">\n      <label>分类粒度<output id=\"outWeight\">0.70<\/output><\/label>\n      <input type=\"range\" id=\"inWeight\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.7\">\n    <\/div>\n  <\/div>\n  <svg id=\"classChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"细粒度分类\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">分类准确率<\/span><b id=\"roAcc\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">粒度<\/span><b id=\"roGran\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"classTip\">岩屑类间差异小（泥岩/页岩、粉砂岩/细砂岩），粗粒度分类容易混淆难分对、漏掉关键岩性变化。细粒度分类学局部纹理特征，区分难分对；混样与污染带来标签噪声，模型学到错误映射会偏低。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 多标签识别 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>多标签识别<\/b>：单样品多组分 → 岩性组分比例<span class=\"qa-algo\">细粒度分类 · 多标签识别<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 3<\/span>\n    <h2>多标签识别：样品 → 组分比例<\/h2>\n    <p class=\"leadline\">看每个样品的岩性组分堆叠（主成分+次成分）。<\/p>\n  <\/div>\n  <svg id=\"multiChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"多标签识别\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">末样主成分<\/span><b id=\"roMain\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">组分<\/span><b id=\"roMix\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"multiTip\">岩屑样品常是混样、含多组分。多标签识别输出组分占比（主成分+次成分），替代目估成分比例。若把样品当单标签，混样只能归一类，丢失组分信息。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 类别不均衡处理 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">少数类加权/重采样 → <b>少数类召回提升<\/b>（罕见岩性不漏）<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 4—6<\/span>\n    <h2>类别不均衡处理：少数类召回 + 复核回流<\/h2>\n    <p class=\"leadline\">切 none/加权/重采样，看少数类召回差多少、复核回流清单。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"balCtl\">\n    <div class=\"sl\">\n      <label>不均衡处理<output id=\"outBal\">加权<\/output><\/label>\n      <input type=\"range\" id=\"inBal\" min=\"0\" max=\"2\" step=\"1\" value=\"1\">\n    <\/div>\n  <\/div>\n  <svg id=\"balChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"类别不均衡处理\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">少数类召回<\/span><b id=\"roRec\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">宏平均<\/span><b id=\"roMacro\">—<\/b><\/div>\n  <\/div>\n  <div class=\"review-list\" id=\"reviewList\"><\/div>\n  <p class=\"tip\" id=\"balTip\">不做不均衡处理，模型全猜多数类、罕见岩性全漏检。加权/重采样让少数类不被淹没，召回显著提升。复核结果回流训练集，模型越用越准、漏检持续下降。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 2<\/b><br>细粒度分类。<\/div>\n    <div><b>实验 2 → STEP 3<\/b><br>多标签组分比例。<\/div>\n    <div><b>实验 3 → STEP 4<\/b><br>不均衡处理 + 回流。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：岩屑图像特征由「类中心 + 噪声」合成，真实类别已知、仅供对比；细粒度分类、多标签识别与不均衡处理均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：岩屑图像怎么一步步变成岩性组分',\n    stages: [\n      { name: '图像接入', tag: '岩屑图像', dur: 4000, draw: function (t, g) { return F.stage1(t); } },\n      { name: '细粒度分类', tag: '区分难分对', dur: 4600, draw: function (t, g) { return F.stage2(t); } },\n      { name: '多标签识别', tag: '组分比例', dur: 4400, draw: function (t, g) { return F.stage3(t); } },\n      { name: '不均衡处理', tag: '少数类召回', dur: 4600, draw: function (t, g) { return F.stage4(t); } },\n      { name: '人工复核', tag: '异常样品', dur: 4200, draw: function (t, g) { return F.stage5(t); } },\n      { name: '成果回流', tag: '更准', dur: 4200, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的岩屑显微图像特征演示细粒度分类、多标签识别与类别不均衡处理。","height":600};
  var META = {"id":"m1-cuttings-litho","sceneId":"m1","title":"岩屑岩性自动识别：细粒度分类 + 多标签 + 类别不均衡"};
  var handle = null;
  var DEF = {"id":"m1-cuttings-litho","sceneId":"m1","title":"岩屑岩性自动识别：细粒度分类 + 多标签 + 类别不均衡","methods":["cv"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"岩屑显微图像","desc":"单井300—800张"},{"label":"标注成本","value":"高","desc":"每类岩性≥500张"},{"label":"可见收益","value":"组分化+省人力","desc":"描述一致可追溯"},{"label":"难度","value":"高","desc":"细粒度+不均衡"}],"lede":"岩屑录井是判断钻遇地层最直接的手段。捞取的岩屑由录井工在显微镜下目估成分、粒级与含油级别，形成岩屑描述表。类间差异小（泥岩/页岩、粉砂岩/细砂岩）、样本不均衡，混样与污染带来标签噪声。智能方法对岩屑显微图像做细粒度分类与多标签识别，输出岩性组分比例，替代人工目估。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p><b>岩屑录井<\/b>是判断钻遇地层最直接的手段，捞取的岩屑由录井工在显微镜下<b>目估<\/b>成分、粒级与含油级别，形成岩屑描述表。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>样品密集<\/b>——每 1—2 m 捞样一次，单井数百个样品<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>类间差异小<\/b>——泥岩/页岩、粉砂岩/细砂岩难分<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>人工目估主观<\/b>——同一块样品不同人可差一个粒级<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"人工目估的问题\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">人工目估 → 主观 · 不一致<\/text><rect x=\"20\" y=\"36\" width=\"280\" height=\"176\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"160\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">显微镜目估<\/text><rect x=\"36\" y=\"70\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"96\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#2b4a72\">每 1—2 m 捞样<\/text><rect x=\"180\" y=\"70\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"230\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">目估成分粒级<\/text><rect x=\"36\" y=\"112\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"96\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">同一块不同人可差<\/text><rect x=\"180\" y=\"112\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"230\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">含油级别靠经验<\/text><text x=\"160\" y=\"180\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#b26a39\" font-weight=\"700\">描述不一致 → 地层判断受影响<\/text><text x=\"160\" y=\"198\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">混样污染 → 标签噪声<\/text><rect x=\"316\" y=\"36\" width=\"284\" height=\"176\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"458\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">为什么难<\/text><text x=\"332\" y=\"82\" font-size=\"9.5\" fill=\"#4d565b\">· 类间差异小（泥岩/页岩）<\/text><text x=\"332\" y=\"104\" font-size=\"9.5\" fill=\"#4d565b\">· 样本不均衡<\/text><text x=\"332\" y=\"126\" font-size=\"9.5\" fill=\"#4d565b\">· 混样污染<\/text><rect x=\"332\" y=\"150\" width=\"252\" height=\"46\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"344\" y=\"170\" font-size=\"8.5\" fill=\"#79828a\">标签噪声 → 描述表不可靠<\/text><text x=\"344\" y=\"186\" font-size=\"8.5\" fill=\"#b26a39\" font-weight=\"700\">需要智能识别<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>对岩屑显微图像做<b>细粒度分类<\/b>与<b>多标签识别<\/b>，输出<b>岩性组分比例<\/b>，替代人工目估。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>细粒度分类<\/b>——区分泥岩/页岩、粉砂岩/细砂岩等难分对<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>多标签识别<\/b>——单样品多组分，输出岩性组分比例<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>不均衡处理<\/b>——少数类加权/重采样，提升召回<\/span><\/div><\/div><p>落地形态：岩屑描述一致、可追溯，录井工程师只做复核。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"岩屑岩性智能识别流程\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">岩屑图像 → 细粒度分类 + 多标签 → 组分比例<\/text><rect x=\"20\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"80\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">岩屑显微图像<\/text><path d=\"M36 78 C60 62 90 76 116 68\" fill=\"none\" stroke=\"#7a8a9a\" stroke-width=\"2.6\"/><text x=\"80\" y=\"130\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">标尺+固定光照<\/text><path d=\"M144 100 L168 100\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"172\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"237\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">细粒度分类<\/text><text x=\"237\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">区分难分对<\/text><text x=\"237\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">多标签组分<\/text><path d=\"M306 100 L330 100\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"334\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"399\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">不均衡处理<\/text><text x=\"399\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">加权/重采样<\/text><text x=\"399\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">提升少数类<\/text><path d=\"M468 100 L492 100\" stroke=\"#2b4a72\" stroke-width=\"1.6\"/><rect x=\"496\" y=\"40\" width=\"104\" height=\"120\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"548\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">组分比例<\/text><text x=\"548\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">描述一致<\/text><text x=\"548\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">可追溯<\/text><text x=\"310\" y=\"210\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">岩屑描述一致 · 可追溯 · 工程师只做复核<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>岩屑显微图像<\/b>：单井 300—800 张，含标尺与固定光照；<b>岩屑描述表<\/b>：对应井深与岩性、含油级别，作为标签；<b>洗样与混样记录<\/b>：样品处理条件，用于分组避免数据泄漏。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"岩屑识别数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">岩屑岩性识别需要的数据<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">岩屑显微图像<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">单井300—800张<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">每类岩性≥500张<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#b26a39\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">岩屑描述表<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">井深+岩性+含油级别<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">作为标签<\/text><rect x=\"20\" y=\"106\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">洗样与混样记录<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">样品处理条件<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">分组避免泄漏<\/text><rect x=\"318\" y=\"106\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"330\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">钻井参数<\/text><text x=\"330\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">井深/钻速/排量<\/text><text x=\"330\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">辅助上下文<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"32\" y=\"202\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">训练策略：细粒度分类 + 多标签识别 + 类别不均衡处理<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>类间差异小<\/b>——泥岩/页岩、粉砂岩/细砂岩难分，需要细粒度特征<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>样本不均衡<\/b>——少数岩性样本少，模型易偏向多数类<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>混样污染<\/b>——洗样不净与上返混样带来标签噪声<\/span><\/div><\/div><p>改进路线按成本从低到高：先用<b>类别不均衡处理<\/b>（加权/重采样）让少数类不被淹没；再加<b>细粒度分类<\/b>区分难分对；最后用<b>多标签识别<\/b>输出组分比例。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"岩屑识别难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 类间差异小<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">泥岩/页岩难分<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">细粒度分类<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">局部纹理特征<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 样本不均衡<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">少数类被淹没<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">类别不均衡处理<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">加权/重采样<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 混样污染<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">标签噪声<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">多标签组分比例<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">输出组分占比<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">不均衡处理 → 细粒度分类 → 多标签识别<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一口井的岩屑岩性识别改造","lead":["某井此前由录井工显微镜下目估岩屑成分、粒级，同一块样品不同人可差一个粒级。目标：用细粒度分类 + 多标签识别输出岩性组分比例，加类别不均衡处理。","注意第 3、4、5 步：细粒度分类、多标签识别、类别不均衡处理是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["井","某生产井"],["采样间隔","每 1—2 m 捞样"],["样品规模","单井 300—800 张"],["识别方式","显微镜目估"],["目标","组分比例+省人力"],["难点","细粒度+不均衡"]],"steps":[{"name":"岩屑图像接入","role":"数据","do":"读入岩屑显微图像与岩屑描述表（井深、岩性、含油级别）。示范页屏 1 顶部可看图像分类。","effect":"带标签的岩屑图像集，每类岩性 ≥ 500 张。","trap":"不同井光照/倍率不一致，直接合并训练会学偏，需统一成像条件。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">图像接入：岩屑显微图像 + 描述表<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">岩屑图像<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">单井300—800张<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">描述表<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">岩性/含油级别<\/text><path d=\"M360 72 L384 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">洗样/混样记录<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">分组避免泄漏<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：光照/倍率不一致 → 合并训练学偏 → 需统一成像<\/text><\/svg>"},{"name":"细粒度分类","role":"算法核心","do":"对岩屑图像做细粒度分类，区分泥岩/页岩、粉砂岩/细砂岩等难分对。示范页屏 1 展示分类。","effect":"难分对的岩性被正确区分，替代人工目估粒级。","trap":"只做粗粒度分类，泥岩/页岩等难分对混淆，漏掉关键岩性变化。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">细粒度分类：图像 → 岩性类别<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">岩屑图像<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">局部纹理<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">细粒度模型<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">区分难分对<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">岩性类别概率<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">泥岩/页岩/粉砂岩<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只做粗粒度 → 难分对混淆 → 漏关键岩性<\/text><\/svg>"},{"name":"多标签识别","role":"算法核心","do":"单样品多组分，识别出岩性组分比例。示范页屏 2 展示组分。","effect":"一个样品输出多组分占比，替代目估成分比例。","trap":"把样品当单标签，混样样品只能归一类，丢失组分信息。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">多标签识别：样品 → 组分比例<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">单样品<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">混样多组分<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">多标签模型<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">多输出占比<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">组分比例<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">泥岩60%+粉砂30%<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：当单标签 → 混样只能归一类 → 丢组分信息<\/text><\/svg>"},{"name":"类别不均衡处理","role":"算法核心","do":"少数类岩性加权或重采样，提升召回。示范页屏 3 展示不均衡处理前后。","effect":"少数类岩性不被淹没，召回显著提升。","trap":"不做不均衡处理，模型全猜多数类，罕见岩性全部漏检。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">不均衡处理：加权/重采样 → 少数类召回<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">不均衡数据<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">少数类被淹没<\/text><path d=\"M188 72 L210 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">加权/重采样<\/text><text x=\"294\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">提升少数类<\/text><path d=\"M378 72 L400 72\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">少数类召回↑<\/text><text x=\"499\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">罕见岩性不漏<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：不处理 → 全猜多数类 → 罕见岩性全漏检<\/text><\/svg>"},{"name":"人工复核","role":"人工确认","do":"模型输出组分比例，工程师只对异常样品复核。示范页屏 3 展示复核清单。","effect":"录井工从逐样目估改为异常复核，效率与一致性提升。","trap":"只看总体准确率，不看少数类召回，罕见岩性错误被掩盖。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">复核：模型组分比例 → 工程师复核<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">组分比例<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">模型输出<\/text><path d=\"M188 72 L210 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">异常复核<\/text><text x=\"294\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">只看异常样品<\/text><path d=\"M378 72 L400 72\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">描述一致<\/text><text x=\"499\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">可追溯<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只看总体准确率 → 少数类错误被掩盖<\/text><\/svg>"},{"name":"成果回流","role":"人工确认","do":"复核结果回流训练集，模型越用越准。示范页屏 3 展示回流清单。","effect":"模型持续改进，少数类岩性越标越全。","trap":"复核结果不回流，模型不知道错在哪，永远漏检。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">回流：复核结果 → 训练集 → 更准<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">复核结果<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">纠正的标签<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">训练集<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">增量更新<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">更准<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">漏检变少<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：复核不回流 → 模型不知道错在哪 → 永远漏检<\/text><\/svg>"}],"metrics":{"title":"怎么算「识别对了」","html":"<p>岩屑识别用 <b>总体准确率<\/b> 与 <b>少数类召回率<\/b> 双重验收；<b>组分比例误差<\/b> 衡量多标签输出。<\/p><p>最终还要看 <b>人工复核占比<\/b>：模型接管常规样品后，工程师只需复核异常样品。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='岩屑识别效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>岩屑识别验收：准确率 × 少数类召回 × 复核占比<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>识别效果<\/text><rect x='40' y='66' width='80' height='52' fill='#d9b78e'/><text x='80' y='96' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>准确 79%<\/text><text x='80' y='112' text-anchor='middle' font-size='8' fill='#8a6b52'>目估粗分<\/text><rect x='180' y='66' width='80' height='52' fill='#2f7d6b'/><text x='220' y='96' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>准确 96%<\/text><text x='220' y='112' text-anchor='middle' font-size='8' fill='#b9d8cb'>细粒度+多标签<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>准确 ↑ 少数类召回 ↑<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>少数类 + 复核<\/text><rect x='340' y='66' width='120' height='52' fill='#e7eef9' stroke='#41699b'/><text x='400' y='92' text-anchor='middle' font-size='9' fill='#2b4a72' font-weight='700'>召回 41%→88%<\/text><text x='400' y='108' text-anchor='middle' font-size='8' fill='#79828a'>不均衡处理<\/text><rect x='470' y='66' width='120' height='52' fill='#e6f1ec' stroke='#2f7d6b'/><text x='530' y='92' text-anchor='middle' font-size='9' fill='#22604f' font-weight='700'>复核占比↓<\/text><text x='530' y='108' text-anchor='middle' font-size='8' fill='#79828a'>只复核异常<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>描述一致 · 可追溯<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 准确率 × 少数类召回 × 复核占比<\/text><\/svg><\/p>"},"fails":[{"name":"类间差异小","why":"泥岩/页岩、粉砂岩/细砂岩难分，粗粒度分类漏掉关键岩性变化。"},{"name":"样本不均衡","why":"少数岩性样本少，模型偏多数类，罕见岩性全部漏检。"},{"name":"混样污染","why":"洗样不净与上返混样带来标签噪声，模型学到错误映射。"},{"name":"成像不一致","why":"不同井光照/倍率不一致，直接合并训练会学偏。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的岩屑显微图像特征演示细粒度分类、多标签识别与类别不均衡处理。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
